#!/usr/bin/env bash
# Ubuntu 24.04. Скопируйте файл на НОВЫЙ сервер; настройки вводятся при запуске.
# Запуск: sudo bash ./install-remnanode.sh
# Проверка значений без установки: bash ./install-remnanode.sh --validate-only
set +x
set -Eeuo pipefail
umask 077

usage() {
  printf '%s\n' 'Скрипт спросит домен, ключ Remnawave, IP панели и порты.' \
    'Установка: sudo bash ./install-remnanode.sh' \
    'Проверка: bash ./install-remnanode.sh --validate-only'
}
mode=install
case "${1:-}" in
  --validate-only) mode=validate ;;
  --help|-h) usage; exit 0 ;;
  '') ;;
  *) usage >&2; exit 2 ;;
esac
if (( $# > 1 )); then usage >&2; exit 2; fi
command -v python3 >/dev/null || { printf '%s\n' 'Нужен python3 (штатно есть в Ubuntu 24.04).' >&2; exit 1; }
installer_work=$(mktemp -d "${TMPDIR:-/tmp}/remna-install.XXXXXXXX")
installer_tty_state=''
cleanup() {
  if [[ -n "$installer_tty_state" ]]; then stty "$installer_tty_state" 2>/dev/null || true; fi
  rm -rf -- "$installer_work"
}
trap cleanup EXIT
trap 'exit 130' INT
trap 'exit 143' TERM

# Распаковка встроенных файлов с проверкой целостности.
python3 - "${BASH_SOURCE[0]}" "$installer_work" '1176fc1946269e8dfedc9016a262bfd891728091a32cd2647f91c47cdeff8caa' <<'PY'
import base64, hashlib, io, pathlib, sys, tarfile
try:
    content = pathlib.Path(sys.argv[1]).read_bytes()
    encoded = content.split(b'\n__REMNA_PAYLOAD_BELOW__\n', 1)[1]
    archive = base64.b64decode(encoded, validate=False)
    if hashlib.sha256(archive).hexdigest() != sys.argv[3]:
        raise ValueError()
    with tarfile.open(fileobj=io.BytesIO(archive), mode='r:gz') as bundle:
        bundle.extractall(sys.argv[2], filter='data')
except Exception:
    print('Повреждён встроенный архив. Используйте исходный файл установщика.', file=sys.stderr)
    sys.exit(1)
PY
# Значения читаются буквально; ключ не отображается в терминале.
ask_value() {
  local name="$1" label="$2" default="${3:-}" hidden="${4:-false}"
  local value='' prompt status
  prompt="$label"
  if [[ -n "$default" ]]; then prompt+=" [$default]"; fi
  prompt+=': '
  while true; do
    status=0
    if [[ "$hidden" == true && -t 0 ]]; then
      installer_tty_state=$(stty -g)
      stty -echo
      printf '%s' "$prompt" >&2
      IFS= read -r value || status=$?
      stty "$installer_tty_state"
      installer_tty_state=''
      printf '\n' >&2
    else
      printf '%s' "$prompt" >&2
      IFS= read -r value || status=$?
    fi
    if (( status != 0 )); then
      printf '\n%s\n' 'Ввод прерван. Установка не запускалась.' >&2
      exit 1
    fi
    value=${value:-$default}
    if [[ -n "$value" ]]; then printf -v "$name" '%s' "$value"; return; fi
    printf '%s\n' 'Обязательное поле. Введите значение.' >&2
  done
}
ssh_default=22
if [[ -n "${SSH_CONNECTION:-}" ]]; then ssh_default=${SSH_CONNECTION##* }; fi
printf '%s\n' 'Настройка Remnawave Node. Enter оставляет значение в скобках.' >&2
ask_value DOMAIN 'Домен новой ноды'
ask_value NODE_SECRET 'Ключ Remnawave (ввод скрыт)' '' true
ask_value PANEL_IP 'IP панели Remnawave' '82.114.226.30'
ask_value SSH_PORT 'SSH-порт сервера' "$ssh_default"
ask_value NODE_PORT 'Порт управления нодой' '2222'
ask_value SELF_STEAL_PORT 'Локальный порт Caddy' '9443'

printf '%s\0' "$DOMAIN" "$NODE_SECRET" "$PANEL_IP" "$SSH_PORT" "$NODE_PORT" "$SELF_STEAL_PORT" |
  python3 "$installer_work/installer/config.py" "$installer_work/vars.json"
unset NODE_SECRET
if [[ "$mode" == validate ]]; then
  printf '%s\n' 'Архив и значения корректны. Установка не запускалась.'
  exit 0
fi
if [[ "${EUID}" != 0 ]]; then printf '%s\n' 'Запустите через sudo bash ./install-remnanode.sh' >&2; exit 1; fi
if [[ ! -f /etc/os-release ]]; then printf '%s\n' 'Нужна Ubuntu 24.04.' >&2; exit 1; fi
. /etc/os-release
if [[ "${ID:-}" != ubuntu || "${VERSION_ID:-}" != 24.04 ]]; then
  printf '%s\n' 'Поддерживается Ubuntu 24.04.' >&2; exit 1
fi
python3 "$installer_work/installer/config.py" --check-ssh "$installer_work/vars.json"

# Только локальный inventory: образец и другие серверы сюда не включены.
cat > "$installer_work/local.ini" <<'INVENTORY'
[nodes]
localhost ansible_connection=local
INVENTORY
export ANSIBLE_CONFIG="$installer_work/ansible.cfg"
export ANSIBLE_COLLECTIONS_PATH=/opt/remna-bootstrap/collections
export ANSIBLE_LOCAL_TEMP="$installer_work/ansible-tmp"
export ANSIBLE_NOCOLOR=1
export ANSIBLE_LOG_PATH=/dev/null
export DEBIAN_FRONTEND=noninteractive
install -d -m 0700 /opt/remna-bootstrap
apt-get update -qq
apt-get install -y -qq python3-venv python3-pip wget
if [[ ! -x /opt/remna-bootstrap/venv/bin/python ]]; then
  python3 -m venv /opt/remna-bootstrap/venv
fi
/opt/remna-bootstrap/venv/bin/pip --quiet install 'ansible-core==2.21.5'
/opt/remna-bootstrap/venv/bin/ansible-galaxy collection install \
  -r "$installer_work/requirements.yml" -p "$ANSIBLE_COLLECTIONS_PATH"
/opt/remna-bootstrap/venv/bin/ansible-playbook "$installer_work/site.yml" \
  -i "$installer_work/local.ini" --extra-vars "@$installer_work/vars.json"
bash "$installer_work/installer/install-motd.sh" "$installer_work"
printf '%s\n' 'Установка завершена. Назначьте новой ноде профиль в панели Remnawave:' \
  "домен: $DOMAIN; self-steal target: 127.0.0.1:$SELF_STEAL_PORT; порт ноды: $NODE_PORT." \
  'Проверьте статус ноды в панели и новое внешнее SSH-подключение.' \
  'Введённый ключ сохранён только в защищённой конфигурации ноды.'
bash "$installer_work/installer/show-node-values.sh"
exit 0
